// Cumulative output/completion tokens (Logic Apps + Foundry)
let la = toscalar(
    traces 
    | where timestamp between (_startTime .. _endTime)   
    | where cloud_RoleName == "multiagentpatterns" 
    | where tostring(customDimensions.EventName) == "WorkflowAgentLoopExecutionCompleted" 
    | summarize sum(tolong(customDimensions.prop__completionTokenCount)));
let fnd = toscalar(
    dependencies 
    | where timestamp between (_startTime .. _endTime)  
    | where cloud_RoleName == ("DirectionsEMEAConciergeAgent") 
        or cloud_RoleName contains "FoundryAgent" 
    | where tostring(customDimensions["gen_ai.operation.name"]) == "chat" 
    | summarize sum(tolong(customDimensions["gen_ai.usage.output_tokens"])));
print ['Output / Completion Tokens'] = la + fnd

// Cumulative estimated cost across agents (tokens for cloud agents + BC Copilot credits)
let laIn = 2.0; let laOut = 8.0;             // gpt-4.1  $/1M
let fIn = 0.25; let fCached = 0.025; let fOut = 2.0;  // gpt-5.4-mini $/1M (input / cached / output)
let creditUsd = 0.01;                        // BC Copilot credit $/credit - edit to contract
let laCost = toscalar(
    traces 
    | where timestamp between (_startTime .. _endTime)  
    | where cloud_RoleName == "multiagentpatterns"
    | where tostring(customDimensions.EventName) == "WorkflowAgentLoopExecutionCompleted"
    | summarize round(sum(tolong(customDimensions.prop__promptTokenCount))/1000000.0*laIn + sum(tolong(customDimensions.prop__completionTokenCount))/1000000.0*laOut, 4));
let fndCost = toscalar(
    dependencies 
    | where timestamp between (_startTime .. _endTime)  
    | where cloud_RoleName == ("DirectionsEMEAConciergeAgent") 
        or cloud_RoleName contains "FoundryAgent" 
    | where tostring(customDimensions["gen_ai.operation.name"]) == "chat"
    | extend i = tolong(customDimensions["gen_ai.usage.input_tokens"]), c = tolong(customDimensions["gen_ai.usage.cache_read.input_tokens"]), o = tolong(customDimensions["gen_ai.usage.output_tokens"])
    | summarize round(sum(i - c)/1000000.0*fIn + sum(c)/1000000.0*fCached + sum(o)/1000000.0*fOut, 4));
let bcCost = toscalar(
    traces 
    | where timestamp between (_startTime .. _endTime)  
    | where tostring(customDimensions.eventId) == "RT0055"
    | summarize round(sum(toreal(customDimensions.copilotCredits)) * creditUsd, 4));
print ['Est. Cost (USD)'] = round(laCost + fndCost + bcCost, 4)

// Estimated cost share by agent (donut) - tokens for cloud agents, credits for BC
let laIn = 2.0; let laOut = 8.0;
let fIn = 0.25; let fCached = 0.025; let fOut = 2.0;
let creditUsd = 0.01;
let la = traces | where timestamp > ago(30d) | where cloud_RoleName == "multiagentpatterns"
  | where tostring(customDimensions.EventName) == "WorkflowAgentLoopExecutionCompleted"
  | summarize InTok = sum(tolong(customDimensions.prop__promptTokenCount)), OutTok = sum(tolong(customDimensions.prop__completionTokenCount))
  | extend AgentType = "Logic Apps (gpt-4.1)", Cost = round(InTok/1000000.0*laIn + OutTok/1000000.0*laOut, 4) | project AgentType, Cost;
let fnd = dependencies | where timestamp > ago(30d) | where cloud_RoleName == "DirectionsEMEAConciergeAgent"
  | where tostring(customDimensions["gen_ai.operation.name"]) == "chat"
  | extend i = tolong(customDimensions["gen_ai.usage.input_tokens"]), c = tolong(customDimensions["gen_ai.usage.cache_read.input_tokens"]), o = tolong(customDimensions["gen_ai.usage.output_tokens"])
  | summarize i = sum(i), c = sum(c), o = sum(o)
  | extend AgentType = "Foundry (gpt-5.4-mini)", Cost = round((i - c)/1000000.0*fIn + c/1000000.0*fCached + o/1000000.0*fOut, 4) | project AgentType, Cost;
let bc = traces | where timestamp > ago(30d) | where tostring(customDimensions.eventId) == "RT0055"
  | summarize cr = sum(toreal(customDimensions.copilotCredits))
  | extend AgentType = "BC Agent (credits)", Cost = round(cr * creditUsd, 4) | project AgentType, Cost;
union la, fnd, bc
| project AgentType, ['Est. Cost (USD)'] = Cost
| order by ['Est. Cost (USD)'] desc

// Token mix by agent (billable input vs cached input vs output); BC & MCS have no token telemetry
let la = traces | where timestamp > ago(30d) | where cloud_RoleName == "multiagentpatterns"
  | where tostring(customDimensions.EventName) == "WorkflowAgentLoopExecutionCompleted"
  | summarize BillableInput = sum(tolong(customDimensions.prop__promptTokenCount)), CachedInput = long(0), OutputTokens = sum(tolong(customDimensions.prop__completionTokenCount))
  | extend AgentType = "Logic Apps (gpt-4.1)" | project AgentType, BillableInput, CachedInput, OutputTokens;
let fnd = dependencies | where timestamp > ago(30d) | where cloud_RoleName == "DirectionsEMEAConciergeAgent"
  | where tostring(customDimensions["gen_ai.operation.name"]) == "chat"
  | summarize BillableInput = sum(tolong(customDimensions["gen_ai.usage.input_tokens"]) - tolong(customDimensions["gen_ai.usage.cache_read.input_tokens"])), CachedInput = sum(tolong(customDimensions["gen_ai.usage.cache_read.input_tokens"])), OutputTokens = sum(tolong(customDimensions["gen_ai.usage.output_tokens"]))
  | extend AgentType = "Foundry (gpt-5.4-mini)" | project AgentType, BillableInput, CachedInput, OutputTokens;
let mcs = customEvents | where timestamp > ago(30d) | where cloud_RoleName == "Microsoft Copilot Studio" | where name == "BotMessageReceived"
  | summarize n = count() | extend AgentType = "Copilot Studio (no tokens)", BillableInput = long(0), CachedInput = long(0), OutputTokens = long(0) | project AgentType, BillableInput, CachedInput, OutputTokens;
let bc = traces | where timestamp > ago(30d) | where tostring(customDimensions.eventId) == "RT0055"
  | summarize n = count() | extend AgentType = "BC Agent (credits, no tokens)", BillableInput = long(0), CachedInput = long(0), OutputTokens = long(0) | project AgentType, BillableInput, CachedInput, OutputTokens;
union la, fnd, mcs, bc
| order by BillableInput desc
